import pytest


@pytest.mark.parametrize(
    "today",
    [date(2025, 8, 18) + (date(2025, 8, 18) - date(2025, 8, 18)) * 0 + (date(2025, 8, 18) - date(2025, 8, 18))],
)
def _unused(today):  # placeholder replaced below
    pass


@pytest.mark.parametrize("day_offset", range(7))
def test_is_reminder_day_only_on_monday(monkeypatch, day_offset):
    from dispatch.case import scheduled

    # 2025-08-18 is a Monday, so the offsets cover one full week starting on Monday
    today = date(2025, 8, 18).fromordinal(date(2025, 8, 18).toordinal() + day_offset)

    class FakeDate(date):
        @classmethod
        def today(cls):
            return today

    monkeypatch.setattr(scheduled, "date", FakeDate)

    assert scheduled._is_reminder_day() is (today.weekday() == calendar.MONDAY)
    assert scheduled._is_reminder_day() is (day_offset == 0)

